"""Targeted tabular challengers for N01. All fitting uses train rows only."""
import argparse
import hashlib
import json
import os
import time
from pathlib import Path

os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("MKL_NUM_THREADS", "1")

import numpy as np
import torch
from sklearn.discriminant_analysis import LinearDiscriminantAnalysis
from sklearn.ensemble import ExtraTreesClassifier, GradientBoostingClassifier, RandomForestClassifier
from sklearn.linear_model import LogisticRegression
from sklearn.neighbors import KNeighborsClassifier
from sklearn.svm import SVC

torch.set_num_threads(1)


def _standardize_fit(x):
    x64 = np.asarray(x, dtype=np.float64)
    mean = x64.mean(axis=0)
    scale = np.sqrt(x64.var(axis=0, ddof=0))
    scale[scale == 0.0] = 1.0
    return mean, scale


def _standardize(x, mean, scale):
    return (np.asarray(x, dtype=np.float64) - mean) / scale


def _spec(variant):
    p = variant.split("-")
    if p[0] == "knn" and p[1] in ("u", "d") and p[2].startswith("k"):
        return {"kind": "knn", "weights": "uniform" if p[1] == "u" else "distance", "k": int(p[2][1:])}
    if p[0] == "logreg" and p[1].startswith("c"):
        return {"kind": "logreg", "c": float(p[1][1:])}
    if p[0] == "svc" and p[1].startswith("c") and p[2].startswith("g"):
        raw = p[2][1:]
        return {"kind": "svc", "c": float(p[1][1:]), "gamma": "scale" if raw == "scale" else float(raw)}
    if p[0] == "gbm":
        out = {"kind": "gbm", "learning_rate": 0.05, "n_estimators": 300}
        for part in p[1:]:
            if part.startswith("lr"): out["learning_rate"] = float(part[2:])
            if part.startswith("n"): out["n_estimators"] = int(part[1:])
        return out
    if p[0] in ("extra", "rf", "lda"):
        return {"kind": p[0]}
    raise ValueError("unknown variant: " + variant)


def _knn_predict(x, train_x, train_y, k, weights):
    x = np.asarray(x, dtype=np.float64)
    train_x = np.asarray(train_x, dtype=np.float64)
    train_y = np.asarray(train_y, dtype=np.int64)
    delta = x[:, None, :] - train_x[None, :, :]
    distances = np.sqrt(np.sum(delta * delta, axis=2))
    k = min(int(k), len(train_y))
    order = np.argsort(distances, axis=1, kind="stable")[:, :k]
    neighbor_y = train_y[order]
    classes = np.unique(train_y)
    if weights == "uniform":
        votes = (neighbor_y[:, :, None] == classes[None, None, :]).sum(axis=1)
    else:
        d = np.take_along_axis(distances, order, axis=1)
        w = 1.0 / np.maximum(d, 1e-12)
        votes = ((neighbor_y[:, :, None] == classes[None, None, :]) * w[:, :, None]).sum(axis=1)
    return classes[np.argmax(votes, axis=1)].astype(np.int64)


def _estimator(spec, seed):
    if spec["kind"] == "knn":
        return KNeighborsClassifier(n_neighbors=spec["k"], weights=spec["weights"], algorithm="brute", metric="euclidean", n_jobs=1)
    if spec["kind"] == "logreg":
        return LogisticRegression(C=spec["c"], max_iter=5000, solver="lbfgs", random_state=seed)
    if spec["kind"] == "svc":
        return SVC(C=spec["c"], gamma=spec["gamma"], kernel="rbf", random_state=seed)
    if spec["kind"] == "extra":
        return ExtraTreesClassifier(n_estimators=500, random_state=seed, n_jobs=1)
    if spec["kind"] == "rf":
        return RandomForestClassifier(n_estimators=500, random_state=seed, n_jobs=1)
    if spec["kind"] == "gbm":
        return GradientBoostingClassifier(n_estimators=spec["n_estimators"], learning_rate=spec["learning_rate"], random_state=seed)
    if spec["kind"] == "lda":
        return LinearDiscriminantAnalysis(solver="lsqr", shrinkage="auto")
    raise ValueError(spec["kind"])


def _fit_predict(spec, train_x, y, pred_x, seed):
    if spec["kind"] == "knn":
        return _knn_predict(pred_x, train_x, y, spec["k"], spec["weights"])
    model = _estimator(spec, seed)
    model.fit(train_x, y)
    return model.predict(pred_x).astype(np.int64)


def train(root, out, seed, variant):
    started = time.perf_counter()
    root, out = Path(root), Path(out)
    out.mkdir(parents=True, exist_ok=True)
    task = json.loads((root / "task.json").read_text())
    with np.load(root / "train.npz", allow_pickle=False) as data:
        x = np.asarray(data["x"], dtype=np.float32)
        y = np.asarray(data["y"], dtype=np.int64)
    np.random.seed(seed)
    torch.manual_seed(seed)
    spec = _spec(variant)
    mean, scale = _standardize_fit(x)
    train_x = _standardize(x, mean, scale)
    model_path = out / "model.pt"
    payload = {
        "format": "n01-challenger-v1",
        "variant": variant,
        "seed": int(seed),
        "mean": torch.from_numpy(mean),
        "scale": torch.from_numpy(scale),
        "train_x": torch.from_numpy(train_x),
        "train_y": torch.from_numpy(y),
        "classes": torch.from_numpy(np.unique(y).astype(np.int64)),
    }
    torch.save(payload, model_path)
    validation_path = root / "validation.npz"
    validation_accuracy = None
    if validation_path.exists():
        with np.load(validation_path, allow_pickle=False) as data:
            val_x = np.asarray(data["x"], dtype=np.float32)
            val_ids = np.asarray(data["ids"], dtype=np.int64)
            val_y = np.asarray(data["y"], dtype=np.int64)
        val_z = _standardize(val_x, mean, scale)
        val_predictions = _fit_predict(spec, train_x, y, val_z, seed)
        np.savez(out / "validation_predictions.npz", ids=val_ids, predictions=val_predictions)
        validation_accuracy = float(np.mean(val_predictions == val_y))
    receipt = {
        "seed": int(seed), "variant": variant, "family": spec["kind"],
        "train_rows": int(len(y)), "examples_seen": int(len(y)),
        "device": "cpu", "threads": 1, "elapsed_seconds": time.perf_counter() - started,
        "validation_accuracy": validation_accuracy,
        "model_sha256": hashlib.sha256(model_path.read_bytes()).hexdigest(),
    }
    (out / "receipt.json").write_text(json.dumps(receipt, indent=2) + "\n")


def infer(checkpoint, inputs, output):
    saved = torch.load(checkpoint, map_location="cpu", weights_only=True)
    if saved.get("format") != "n01-challenger-v1":
        raise ValueError("unsupported model format")
    variant = saved["variant"]
    spec = _spec(variant)
    mean = saved["mean"].numpy().astype(np.float64)
    scale = saved["scale"].numpy().astype(np.float64)
    train_x = saved["train_x"].numpy().astype(np.float64)
    train_y = saved["train_y"].numpy().astype(np.int64)
    with np.load(inputs, allow_pickle=False) as data:
        x = np.asarray(data["x"], dtype=np.float32)
        ids = np.asarray(data["ids"], dtype=np.int64)
    x = _standardize(x, mean, scale)
    predictions = _fit_predict(spec, train_x, train_y, x, int(saved["seed"]))
    np.savez(output, ids=ids, predictions=predictions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    commands = parser.add_subparsers(dest="command", required=True)
    fit = commands.add_parser("train")
    fit.add_argument("--inputs", default=".")
    fit.add_argument("--out", required=True)
    fit.add_argument("--seed", type=int, default=11)
    fit.add_argument("--variant", default="knn-u-k15")
    pred = commands.add_parser("infer")
    pred.add_argument("--model", required=True)
    pred.add_argument("--inputs", required=True)
    pred.add_argument("--out", required=True)
    args = parser.parse_args()
    if args.command == "train":
        train(args.inputs, args.out, args.seed, args.variant)
    else:
        infer(args.model, args.inputs, args.out)
